/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

// Token bucket policy
class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity;
    this.refill = refill;
    this.per = per;
  }

  createKeyState() {
    return {
      tokens: this.capacity, // starts full
      lastTick: null,
    };
  }

  allow(keyState, tick) {
    // Calculate what the state would be after advancing, without modifying
    let tokens = keyState.tokens;
    if (keyState.lastTick !== null) {
      const elapsed = tick - keyState.lastTick;
      const refilled = (this.refill * elapsed) / this.per;
      tokens = Math.min(this.capacity, tokens + refilled);
    }
    return tokens >= 1;
  }

  advance(keyState, tick) {
    // Actually advance the state
    if (keyState.lastTick !== null) {
      const elapsed = tick - keyState.lastTick;
      const refilled = (this.refill * elapsed) / this.per;
      keyState.tokens = Math.min(this.capacity, keyState.tokens + refilled);
    }
    keyState.lastTick = tick;
  }

  record(keyState) {
    keyState.tokens -= 1;
  }
}

// Sliding window policy
class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit;
    this.span = span;
  }

  createKeyState() {
    return {
      ticks: [],
    };
  }

  allow(keyState, tick) {
    // Calculate what the state would be after advancing, without modifying
    const cutoff = tick - this.span;
    const keptTicks = keyState.ticks.filter(t => t > cutoff);
    return keptTicks.length < this.limit;
  }

  advance(keyState, tick) {
    // Actually advance the state (forget old ticks)
    const cutoff = tick - this.span;
    keyState.ticks = keyState.ticks.filter(t => t > cutoff);
  }

  record(keyState, tick) {
    keyState.ticks.push(tick);
  }
}

function isValidName(name) {
  return /^[A-Za-z0-9_./:\-+]+$/.test(name);
}

function isValidInteger(str, minValue) {
  // No sign, no leading zero unless it's exactly "0"
  if (!/^\d+$/.test(str)) {
    return false;
  }
  if (str.length > 1 && str[0] === '0') {
    return false;
  }
  const value = parseInt(str, 10);
  return value >= minValue;
}

async function main() {
  const mode = process.argv[2];

  if (mode !== 'replay' && mode !== 'summary') {
    process.stderr.write('error: usage: cli.js replay|summary\n');
    process.exit(2);
  }

  // Read all input
  let input = '';
  for await (const chunk of process.stdin) {
    input += chunk;
  }

  // Parse input
  const lines = input.split('\n');
  const policies = {}; // name -> policy
  const routes = []; // {prefix, policies: [policy], names: [name]}
  const events = []; // {tick, key}
  let lastTick = -1;
  let firstEventLineNum = null;

  let lineNum = 0;
  for (const line of lines) {
    lineNum++;
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const parts = trimmed.split(/\s+/);
    const directive = parts[0];

    if (directive === 'bucket') {
      if (firstEventLineNum !== null) {
        process.stderr.write(
          `error: line ${lineNum}: declarations must come before the first event\n`
        );
        process.exit(2);
      }
      if (parts.length !== 5) {
        process.stderr.write(
          `error: line ${lineNum}: expected bucket <name> <capacity> <refill> <per>\n`
        );
        process.exit(2);
      }
      const [, name, capacityStr, refillStr, perStr] = parts;

      // Validate name
      if (!isValidName(name)) {
        process.stderr.write(
          `error: line ${lineNum}: invalid policy name ${name}\n`
        );
        process.exit(2);
      }

      // Check duplicate
      if (policies[name]) {
        process.stderr.write(
          `error: line ${lineNum}: policy ${name} is declared twice\n`
        );
        process.exit(2);
      }

      // Parse numbers
      if (!isValidInteger(capacityStr, 1)) {
        process.stderr.write(
          `error: line ${lineNum}: capacity must be an integer of at least 1\n`
        );
        process.exit(2);
      }
      if (!isValidInteger(refillStr, 0)) {
        process.stderr.write(
          `error: line ${lineNum}: refill must be an integer of at least 0\n`
        );
        process.exit(2);
      }
      if (!isValidInteger(perStr, 1)) {
        process.stderr.write(
          `error: line ${lineNum}: per must be an integer of at least 1\n`
        );
        process.exit(2);
      }

      const capacity = parseInt(capacityStr, 10);
      const refill = parseInt(refillStr, 10);
      const per = parseInt(perStr, 10);

      policies[name] = new TokenBucket(capacity, refill, per);
    } else if (directive === 'window') {
      if (firstEventLineNum !== null) {
        process.stderr.write(
          `error: line ${lineNum}: declarations must come before the first event\n`
        );
        process.exit(2);
      }
      if (parts.length !== 4) {
        process.stderr.write(
          `error: line ${lineNum}: expected window <name> <limit> <span>\n`
        );
        process.exit(2);
      }
      const [, name, limitStr, spanStr] = parts;

      // Validate name
      if (!isValidName(name)) {
        process.stderr.write(
          `error: line ${lineNum}: invalid policy name ${name}\n`
        );
        process.exit(2);
      }

      // Check duplicate
      if (policies[name]) {
        process.stderr.write(
          `error: line ${lineNum}: policy ${name} is declared twice\n`
        );
        process.exit(2);
      }

      // Parse numbers
      if (!isValidInteger(limitStr, 0)) {
        process.stderr.write(
          `error: line ${lineNum}: limit must be an integer of at least 0\n`
        );
        process.exit(2);
      }
      if (!isValidInteger(spanStr, 1)) {
        process.stderr.write(
          `error: line ${lineNum}: span must be an integer of at least 1\n`
        );
        process.exit(2);
      }

      const limit = parseInt(limitStr, 10);
      const span = parseInt(spanStr, 10);

      policies[name] = new SlidingWindow(limit, span);
    } else if (directive === 'route') {
      if (firstEventLineNum !== null) {
        process.stderr.write(
          `error: line ${lineNum}: declarations must come before the first event\n`
        );
        process.exit(2);
      }
      if (parts.length < 3) {
        process.stderr.write(
          `error: line ${lineNum}: expected route <prefix> <policy>...\n`
        );
        process.exit(2);
      }
      const prefix = parts[1];
      const policyNames = parts.slice(2);

      // Validate prefix
      if (!isValidName(prefix)) {
        process.stderr.write(
          `error: line ${lineNum}: invalid route prefix ${prefix}\n`
        );
        process.exit(2);
      }

      // Check duplicate prefix
      if (routes.some(r => r.prefix === prefix)) {
        process.stderr.write(
          `error: line ${lineNum}: prefix ${prefix} is routed twice\n`
        );
        process.exit(2);
      }

      // Validate all policies exist
      const routePolicies = [];
      for (const policyName of policyNames) {
        if (!policies[policyName]) {
          process.stderr.write(
            `error: line ${lineNum}: unknown policy ${policyName}\n`
          );
          process.exit(2);
        }
        routePolicies.push(policies[policyName]);
      }

      routes.push({ prefix, policies: routePolicies, names: policyNames });
    } else if (directive === 'event') {
      if (firstEventLineNum === null) {
        firstEventLineNum = lineNum;
      }
      if (parts.length !== 3) {
        process.stderr.write(
          `error: line ${lineNum}: expected event <tick> <key>\n`
        );
        process.exit(2);
      }
      const [, tickStr, key] = parts;

      // Validate tick
      if (!isValidInteger(tickStr, 0)) {
        process.stderr.write(
          `error: line ${lineNum}: tick must be an integer of at least 0\n`
        );
        process.exit(2);
      }

      const tick = parseInt(tickStr, 10);

      // Check tick order
      if (tick < lastTick) {
        process.stderr.write(
          `error: line ${lineNum}: tick ${tick} is before tick ${lastTick}\n`
        );
        process.exit(2);
      }
      lastTick = tick;

      // Validate key
      if (!isValidName(key)) {
        process.stderr.write(
          `error: line ${lineNum}: invalid key ${key}\n`
        );
        process.exit(2);
      }

      events.push({ tick, key });
    } else {
      process.stderr.write(
        `error: line ${lineNum}: unknown directive ${directive}\n`
      );
      process.exit(2);
    }
  }

  // Sort routes by prefix length (longest first) for matching
  routes.sort((a, b) => b.prefix.length - a.prefix.length);

  // Process events
  const keyStats = {}; // key -> {allowed, denied}
  const results = [];

  for (const { tick, key } of events) {
    // Find matching route (longest prefix)
    let matchingRoute = null;
    for (const route of routes) {
      if (key.startsWith(route.prefix)) {
        matchingRoute = route;
        break;
      }
    }

    // If no route matches, always allow
    if (!matchingRoute) {
      results.push({ tick, key, allowed: true });
      if (!keyStats[key]) {
        keyStats[key] = { allowed: 0, denied: 0 };
      }
      keyStats[key].allowed++;
      continue;
    }

    // Initialize key states if needed for this route
    for (const policy of matchingRoute.policies) {
      if (!policy.keyStates) {
        policy.keyStates = {};
      }
      if (!policy.keyStates[key]) {
        policy.keyStates[key] = policy.createKeyState();
      }
    }

    // Check all policies on the route
    let denied = false;
    let denyingPolicyName = null;
    for (let i = 0; i < matchingRoute.policies.length; i++) {
      const policy = matchingRoute.policies[i];
      const state = policy.keyStates[key];
      if (!policy.allow(state, tick)) {
        denied = true;
        denyingPolicyName = matchingRoute.names[i];
        break;
      }
    }

    if (denied) {
      results.push({ tick, key, allowed: false, policy: denyingPolicyName });
      if (!keyStats[key]) {
        keyStats[key] = { allowed: 0, denied: 0 };
      }
      keyStats[key].denied++;
    } else {
      // Advance all policies and record
      for (const policy of matchingRoute.policies) {
        const state = policy.keyStates[key];
        policy.advance(state, tick);
        policy.record(state, tick);
      }
      results.push({ tick, key, allowed: true });
      if (!keyStats[key]) {
        keyStats[key] = { allowed: 0, denied: 0 };
      }
      keyStats[key].allowed++;
    }
  }

  // Output
  if (mode === 'replay') {
    for (const result of results) {
      if (result.allowed) {
        console.log(`${result.tick} ${result.key} allow`);
      } else {
        console.log(`${result.tick} ${result.key} deny ${result.policy}`);
      }
    }
  } else if (mode === 'summary') {
    // Sort keys
    const sortedKeys = Object.keys(keyStats).sort();
    for (const key of sortedKeys) {
      const stats = keyStats[key];
      console.log(`${key} allowed=${stats.allowed} denied=${stats.denied}`);
    }

    // Total
    let totalAllowed = 0;
    let totalDenied = 0;
    for (const stats of Object.values(keyStats)) {
      totalAllowed += stats.allowed;
      totalDenied += stats.denied;
    }
    console.log(`total allowed=${totalAllowed} denied=${totalDenied}`);
  }

  process.exit(0);
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`);
  process.exit(2);
});
"}

