// Validate all policies exist
const routePolicies = [];
for (const policyName of policyNames) {
  if (!policies.has(policyName)) {
    fail(`line ${lineNum}: unknown policy ${policyName}`);
  }
  routePolicies.push(policies.get(policyName));
}

routes.push({ prefix, policies: routePolicies, names: policyNames });
